'use server';

import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { drizzleDb } from '@/lib/drizzle';
import { workspaces, creditLedger } from '@/lib/schema';
import { eq, sql } from 'drizzle-orm';

export async function transferWorkspaceCredits(sourceWorkspaceId: string, destinationWorkspaceId: string, credits: number) {
  const session = await getServerSession(authOptions);
  if (!session?.user) {
    return { error: 'Authentication required' };
  }
  if (credits <= 0) return { error: 'Invalid credit amount' };

  await drizzleDb.transaction(async (tx) => {
    await tx.update(workspaces)
      .set({ balanceCredits: sql`${workspaces.balanceCredits} - ${credits}` })
      .where(eq(workspaces.id, sourceWorkspaceId));

    await tx.update(workspaces)
      .set({ balanceCredits: sql`${workspaces.balanceCredits} + ${credits}` })
      .where(eq(workspaces.id, destinationWorkspaceId));

    await tx.insert(creditLedger).values({
      fromWorkspace: sourceWorkspaceId,
      toWorkspace: destinationWorkspaceId,
      amount: credits,
      createdAt: new Date()
    });
  });

  return { success: true, transferred: credits };
}

corrected_code:
'use server';

import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { drizzleDb } from '@/lib/drizzle';
import { workspaces, workspaceMembers, creditLedger } from '@/lib/schema';
import { eq, and, sql } from 'drizzle-orm';

export async function transferWorkspaceCredits(sourceWorkspaceId: string, destinationWorkspaceId: string, credits: number) {
  const session = await getServerSession(authOptions);
  if (!session?.user) {
    return { error: 'Authentication required' };
  }
  if (credits <= 0) return { error: 'Invalid credit amount' };

  const [member] = await drizzleDb.select()
    .from(workspaceMembers)
    .where(and(
      eq(workspaceMembers.workspaceId, sourceWorkspaceId),
      eq(workspaceMembers.userId, session.user.id),
      eq(workspaceMembers.role, 'BILLING_ADMIN')
    ));
  if (!member) {
    return { error: 'Forbidden: unauthorized to transfer credits from source workspace' };
  }

  await drizzleDb.transaction(async (tx) => {
    await tx.update(workspaces)
      .set({ balanceCredits: sql`${workspaces.balanceCredits} - ${credits}` })
      .where(eq(workspaces.id, sourceWorkspaceId));

    await tx.update(workspaces)
      .set({ balanceCredits: sql`${workspaces.balanceCredits} + ${credits}` })
      .where(eq(workspaces.id, destinationWorkspaceId));

    await tx.insert(creditLedger).values({
      fromWorkspace: sourceWorkspaceId,
      toWorkspace: destinationWorkspaceId,
      amount: credits,
      createdAt: new Date()
    });
  });

  return { success: true, transferred: credits };
}
